BEGIN;
ALTER TABLE "ApplicationPreparation" ADD COLUMN "buildBaseImageId" TEXT CHECK("buildBaseImageId" IS NULL OR "buildBaseImageId" ~ '^sha256:[a-f0-9]{64}$'),ADD COLUMN "buildWriteStartedAt" TIMESTAMP(3),ADD COLUMN "statusWriteStartedAt" TIMESTAMP(3),ADD COLUMN "validationImageId" TEXT CHECK("validationImageId" IS NULL OR "validationImageId" ~ '^sha256:[a-f0-9]{64}$'),ADD COLUMN "validationArchiveDigest" TEXT CHECK("validationArchiveDigest" IS NULL OR "validationArchiveDigest" ~ '^[a-f0-9]{64}$'),ADD COLUMN "validationSize" INTEGER,ADD COLUMN "technicalTestPassed" BOOLEAN NOT NULL DEFAULT false,ADD COLUMN "pipelineId" INTEGER,ADD COLUMN "statusId" INTEGER;
ALTER TABLE "ApplicationPreparation" ADD CONSTRAINT "ApplicationPreparation_verified" CHECK(state<>'succeeded' OR kind<>'publish' OR "buildBaseImageId" IS NULL OR ("technicalTestPassed" AND "validationImageId" IS NOT NULL AND "validationArchiveDigest" IS NOT NULL AND "validationSize" IS NOT NULL AND "validationSize">0 AND "pipelineId" IS NOT NULL AND "pipelineId">0 AND "statusId" IS NOT NULL AND "statusId">0));
CREATE OR REPLACE FUNCTION validate_application_preparation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE repo "Repository";p "ApplicationPreparation";
BEGIN
 IF TG_OP='INSERT' THEN
  SELECT * INTO repo FROM "Repository" WHERE id=NEW."repositoryId";
  IF NOT EXISTS(SELECT 1 FROM "Item" WHERE id=NEW."systemId" AND kind='system') OR repo.id IS NULL OR repo."systemId"<>NEW."systemId" OR repo.version<>NEW."repositoryVersion" OR repo."gitlabProjectId"<>NEW."projectId" OR NEW.number<>coalesce((SELECT max(number)+1 FROM "ApplicationPreparation" WHERE "systemId"=NEW."systemId"),1) THEN RAISE EXCEPTION 'Preparation requires exact System repository and sequence'; END IF;
  IF NEW."parentId" IS NOT NULL THEN
   SELECT * INTO p FROM "ApplicationPreparation" WHERE id=NEW."parentId";
   IF p.id IS NULL OR p.kind<>'publish' OR p.state<>'succeeded' OR p."resolvedAt" IS NOT NULL OR (p."systemId",p."repositoryId",p."repositoryVersion",p."projectId",p."templateVersion",p."contentDigest",p.files,p."baseSha",p.branch,p."targetBranch",p."commitSha",p.iid,p.url) IS DISTINCT FROM (NEW."systemId",NEW."repositoryId",NEW."repositoryVersion",NEW."projectId",NEW."templateVersion",NEW."contentDigest",NEW.files,NEW."baseSha",NEW.branch,NEW."targetBranch",NEW."commitSha",NEW.iid,NEW.url) THEN RAISE EXCEPTION 'Step must preserve exact published preparation'; END IF;
  END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['state','version','message','leaseId','leaseUntil','commitWriteStartedAt','mrWriteStartedAt','writeStartedAt','buildWriteStartedAt','statusWriteStartedAt','validationImageId','validationArchiveDigest','validationSize','technicalTestPassed','pipelineId','statusId','commitSha','iid','url','mrState','confirmedAt','integrationSha','mergedAt','resolvedAt','resolvedById','resolvedByName','resolutionReason','updatedAt']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','version','message','leaseId','leaseUntil','commitWriteStartedAt','mrWriteStartedAt','writeStartedAt','buildWriteStartedAt','statusWriteStartedAt','validationImageId','validationArchiveDigest','validationSize','technicalTestPassed','pipelineId','statusId','commitSha','iid','url','mrState','confirmedAt','integrationSha','mergedAt','resolvedAt','resolvedById','resolvedByName','resolutionReason','updatedAt']) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'Preserve preparation intent and version'; END IF;
  IF OLD."commitWriteStartedAt" IS NOT NULL AND NEW."commitWriteStartedAt" IS DISTINCT FROM OLD."commitWriteStartedAt" OR OLD."mrWriteStartedAt" IS NOT NULL AND NEW."mrWriteStartedAt" IS DISTINCT FROM OLD."mrWriteStartedAt" OR OLD."writeStartedAt" IS NOT NULL AND NEW."writeStartedAt" IS DISTINCT FROM OLD."writeStartedAt" OR OLD."commitSha" IS NOT NULL AND NEW."commitSha" IS DISTINCT FROM OLD."commitSha" OR OLD.iid IS NOT NULL AND NEW.iid IS DISTINCT FROM OLD.iid OR OLD.url IS NOT NULL AND NEW.url IS DISTINCT FROM OLD.url OR OLD."confirmedAt" IS NOT NULL AND NEW."confirmedAt" IS DISTINCT FROM OLD."confirmedAt" OR OLD."integrationSha" IS NOT NULL AND NEW."integrationSha" IS DISTINCT FROM OLD."integrationSha" OR OLD."mergedAt" IS NOT NULL AND NEW."mergedAt" IS DISTINCT FROM OLD."mergedAt" OR OLD.state='succeeded' AND NEW.state<>'succeeded' THEN RAISE EXCEPTION 'Preserve known preparation effects'; END IF;
  IF OLD."resolvedAt" IS NOT NULL AND (NEW."resolvedAt",NEW."resolvedById",NEW."resolvedByName",NEW."resolutionReason") IS DISTINCT FROM (OLD."resolvedAt",OLD."resolvedById",OLD."resolvedByName",OLD."resolutionReason") THEN RAISE EXCEPTION 'Preserve preparation resolution'; END IF;
 END IF;
 IF NEW."resolvedAt" IS NOT NULL AND (NEW."resolvedById" IS NULL OR NEW."resolvedByName" IS NULL OR length(btrim(coalesce(NEW."resolutionReason",''))) NOT BETWEEN 10 AND 2000) THEN RAISE EXCEPTION 'Preparation resolution requires author and reason'; END IF;
 IF TG_OP='UPDATE' AND (OLD."buildWriteStartedAt" IS NOT NULL AND NEW."buildWriteStartedAt" IS DISTINCT FROM OLD."buildWriteStartedAt" OR OLD."statusWriteStartedAt" IS NOT NULL AND NEW."statusWriteStartedAt" IS DISTINCT FROM OLD."statusWriteStartedAt" OR OLD."validationImageId" IS NOT NULL AND NEW."validationImageId" IS DISTINCT FROM OLD."validationImageId" OR OLD."validationArchiveDigest" IS NOT NULL AND NEW."validationArchiveDigest" IS DISTINCT FROM OLD."validationArchiveDigest" OR OLD."validationSize" IS NOT NULL AND NEW."validationSize" IS DISTINCT FROM OLD."validationSize" OR OLD."technicalTestPassed" AND NOT NEW."technicalTestPassed" OR OLD."pipelineId" IS NOT NULL AND NEW."pipelineId" IS DISTINCT FROM OLD."pipelineId" OR OLD."statusId" IS NOT NULL AND NEW."statusId" IS DISTINCT FROM OLD."statusId") THEN RAISE EXCEPTION 'Preserve preparation technical evidence'; END IF;
 RETURN NEW;
END; $$;
COMMIT;
